const messages = document.querySelectorAll(
  '[data-scroll-anchor-root="true"][id^="response-"]'
);

const users = document.querySelectorAll(
  '[data-testid="user-message"]'
).length;

const assistants = document.querySelectorAll(
  '[data-testid="assistant-message"]'
).length;

if (messages.length === 0) {
  throw new Error(
    "未找到 Grok 对话，请确认当前页面是聊天页面"
  );
}

automaSetVariable("grokPageCheck", {
  mountedMessages: messages.length,
  users,
  assistants,
  url: location.href
});

console.log(
  "[Grok export] page check",
  {
    mountedMessages: messages.length,
    users,
    assistants
  }
);

const preview = text =>
  text.length > 30
    ? text.slice(0, 30) + "…"
    : text;

window.__grokCopiedText = null;
window.__grokCopySeq = 0;
window.__grokLastReadSeq = 0;

if (!window.__grokClipboardInstalled) {
  window.__grokClipboardInstalled = true;

  const clipboard = navigator.clipboard;
  window.__grokOriginalClipboardWriteText =
    clipboard?.writeText;

  window.__grokOriginalClipboardWrite =
    clipboard?.write;

  if (clipboard?.writeText) {
    clipboard.writeText = async function (text) {
      window.__grokCopiedText = text;
      window.__grokCopySeq++;

      console.log(
        "[Grok export] writeText:",
        window.__grokCopySeq,
        preview(text)
      );

      // 不真正写入系统剪贴板
      return;
    };
  }

  if (clipboard?.write) {
    clipboard.write = async function (items) {
      console.log(
        "[Grok export] write() called",
        items.length
      );

      for (const item of items) {
        if (!item.types?.includes("text/plain")) {
          continue;
        }

        const blob =
          await item.getType("text/plain");

        const text =
          await blob.text();

        window.__grokCopiedText = text;
        window.__grokCopySeq++;

        console.log(
          "[Grok export] write:",
          window.__grokCopySeq,
          preview(text)
        );

        return;
      }

      console.warn(
        "[Grok export] write() 中没有 text/plain"
      );
    };
  }
}

console.log(
  "[Grok export] clipboard interceptor ready"
);

automaSetVariable("conversation", []);
automaSetVariable("currentMessageSelector", "");
automaSetVariable("currentMessageId", "");
automaSetVariable("currentMessageRole", "");
automaSetVariable("currentMessageFound", "no");
automaSetVariable("grokDone", false);

window.__grokSeen = new Set();
window.__grokIdleRounds = 0;
window.__grokElementKeys = new WeakMap();
window.__grokMountedKeySeq = 0;

console.log(
  "[Grok export] state initialized"
);

const messages = [
  ...document.querySelectorAll(
    '[data-scroll-anchor-root="true"][id^="response-"]'
  )
];

const getRole = element => {
  if (element.matches('[data-testid="user-message"]') ||
      element.querySelector('[data-testid="user-message"]')) {
    return "user";
  }

  if (element.matches('[data-testid="assistant-message"]') ||
      element.querySelector('[data-testid="assistant-message"]')) {
    return "assistant";
  }

  return null;
};

const getMessageKey = (element, role) => {
  const keyedDescendant = element.querySelector(
    '[data-message-id], [data-turn-id]'
  );

  const stablePart =
    element.getAttribute("data-message-id") ||
    element.getAttribute("data-turn-id") ||
    element.getAttribute("data-message-index") ||
    element.getAttribute("data-turn-index") ||
    element.getAttribute("aria-posinset") ||
    element.id ||
    keyedDescendant?.getAttribute("data-message-id") ||
    keyedDescendant?.getAttribute("data-turn-id");

  const fingerprint =
    role + "\u0000" + element.innerText.trim();

  const previous =
    window.__grokElementKeys.get(element);

  if (previous?.fingerprint === fingerprint) {
    element.setAttribute(
      "data-palace-export-key",
      previous.key
    );

    return previous.key;
  }

  const key = stablePart
    ? role + ":" + stablePart
    : role + ":mounted:" +
      ++window.__grokMountedKeySeq;

  window.__grokElementKeys.set(
    element,
    { fingerprint, key }
  );

  element.setAttribute(
    "data-palace-export-key",
    key
  );

  return key;
};

let found = null;

for (const element of messages) {
  const role = getRole(element);

  if (!role) {
    continue;
  }

  const id = getMessageKey(element, role);

  if (!window.__grokSeen.has(id)) {
    found = { element, id, role };
    break;
  }
}

if (!found) {
  automaSetVariable("currentMessageFound", "no");
  automaSetVariable("currentMessageSelector", "");
  automaSetVariable("currentMessageId", "");
  automaSetVariable("currentMessageRole", "");

  console.log(
    "[Grok export] no new mounted message"
  );
} else {
  const selector =
    '[data-palace-export-key="' +
    CSS.escape(found.id) +
    '"]';

  automaSetVariable("currentMessageFound", "yes");
  automaSetVariable("currentMessageSelector", selector);
  automaSetVariable("currentMessageId", found.id);
  automaSetVariable("currentMessageRole", found.role);

  console.log(
    "[Grok export] next message",
    {
      id: found.id,
      role: found.role,
      selector
    }
  );
}

const selector = automaRefData(
  "variables",
  "currentMessageSelector"
);

const role = automaRefData(
  "variables",
  "currentMessageRole"
);

const element = document.querySelector(selector);

if (!element) {
  throw new Error(
    `找不到当前消息: ${selector}`
  );
}

let buttonSelector;

if (role === "user") {
  buttonSelector = 'button[aria-label="Copy"]';
} else if (role === "assistant") {
  buttonSelector = 'button[aria-label="Copy response"]';
} else {
  throw new Error(
    `无法识别消息角色: ${role}`
  );
}

const button = element.querySelector(buttonSelector);

if (!button) {
  throw new Error(
    `找不到 ${role} 消息的复制按钮: ${selector}`
  );
}

button.click();

console.log(
  "[Grok export] copy clicked",
  { role, selector }
);

const seq = window.__grokCopySeq || 0;
const lastSeq = window.__grokLastReadSeq || 0;
const text = window.__grokCopiedText;

if (seq <= lastSeq) {
  throw new Error(
    `本轮没有捕获到新的复制内容: seq=${seq}, last=${lastSeq}`
  );
}

if (typeof text !== "string") {
  throw new Error("捕获到的复制内容不是字符串");
}

const id = automaRefData(
  "variables",
  "currentMessageId"
);

const role = automaRefData(
  "variables",
  "currentMessageRole"
);

if (!id) {
  throw new Error("缺少 currentMessageId");
}

if (role !== "user" && role !== "assistant") {
  throw new Error(
    `无法识别 role: ${role}`
  );
}

const conversation = automaRefData(
  "variables",
  "conversation"
) || [];

conversation.push({
  role,
  content: text,
  messageId: id
});

window.__grokSeen.add(id);
window.__grokLastReadSeq = seq;

automaSetVariable("conversation", conversation);

console.log(
  "[Grok export] consumed",
  {
    id,
    role,
    total: conversation.length
  }
);

const findScrollRoot = () => {
  const message = document.querySelector(
    '[data-scroll-anchor-root="true"][id^="response-"]'
  );

  for (
    let element = message?.parentElement;
    element;
    element = element.parentElement
  ) {
    const overflowY =
      getComputedStyle(element).overflowY;

    if (
      /(auto|scroll)/.test(overflowY) &&
      element.scrollHeight > element.clientHeight
    ) {
      return element;
    }
  }

  return document.scrollingElement;
};

const element = findScrollRoot();

if (!element) {
  throw new Error(
    "无法找到 Grok 对话滚动容器"
  );
}

const before = element.scrollTop;
const distance = Math.max(
  element.clientHeight * 0.75,
  500
);

element.scrollBy({
  top: distance,
  behavior: "instant"
});

const after = element.scrollTop;

console.log(
  "[Grok export] scroll down",
  {
    before,
    after,
    moved: after - before,
    distance,
    scrollHeight: element.scrollHeight,
    clientHeight: element.clientHeight,
    remaining:
      element.scrollHeight -
      element.clientHeight -
      after
  }
);

