  if (element.matches('[data-testid="user-message"]') ||
      element.querySelector('[data-testid="user-message"]')) {
    return "user";
  }

  if (element.matches('[data-testid="assistant-message"]') ||
      element.querySelector('[data-testid="assistant-message"]')) {
    return "assistant";
  }

  return null;
};

