  );

  const stablePart =
    element.getAttribute("data-message-id") ||
    element.getAttribute("data-turn-id") ||
    element.getAttribute("data-message-index") ||
    element.getAttribute("data-turn-index") ||
    element.getAttribute("aria-posinset") ||
    element.id ||
    keyedDescendant?.getAttribute("data-message-id") ||
    keyedDescendant?.getAttribute("data-turn-id");

  const fingerprint =
    role + "\u0000" + element.innerText.trim();

  const previous =
    window.__grokElementKeys.get(element);

  if (previous?.fingerprint === fingerprint) {
    element.setAttribute(
