      ++window.__grokMountedKeySeq;

  window.__grokElementKeys.set(
    element,
    { fingerprint, key }
  );

  element.setAttribute(
    "data-palace-export-key",
    key
  );

  return key;
};

const element = findScrollRoot();

if (!element) {
  throw new Error(
    "无法找到 Grok 对话滚动容器"
  );
}

const nearBottom =
  element.scrollTop + element.clientHeight >=
  element.scrollHeight - 120;

const mountedMessages = [
  ...document.querySelectorAll(
    '[data-scroll-anchor-root="true"][id^="response-"]'
  )
];

const hasUnseen = mountedMessages.some(message => {
  const role = getRole(message);
  if (!role) return false;

  const id = getMessageKey(message, role);
  return !window.__grokSeen.has(id);
});

if (hasUnseen) {
  window.__grokIdleRounds = 0;
} else {
  window.__grokIdleRounds =
    (window.__grokIdleRounds || 0) + 1;
}

const done =
  nearBottom &&
  !hasUnseen &&
  window.__grokIdleRounds >= 3;

automaSetVariable("grokDone", done);

console.log(
  "[Grok export] check done",
  {
    nearBottom,
    hasUnseen,
    idleRounds: window.__grokIdleRounds,
    done,
    scrollTop: element.scrollTop,
    scrollHeight: element.scrollHeight,
    clientHeight: element.clientHeight
  }
);

const clipboard = navigator.clipboard;

if (clipboard) {
  if (window.__grokOriginalClipboardWriteText) {
    clipboard.writeText =
      window.__grokOriginalClipboardWriteText;
  }

  if (window.__grokOriginalClipboardWrite) {
    clipboard.write =
      window.__grokOriginalClipboardWrite;
  }
}

window.__grokClipboardInstalled = false;

console.log(
  "[Grok export] clipboard interceptor restored"
);
